-- Sample BI dashboards, seeded into every account.
--
-- Three curated dashboards built on the bundled sample datasets
-- (saas_sales, q3_budget_variance, siem_alerts) show off the BI
-- workspace: KPIs, trend + forecast lines, geo bubble maps, treemaps,
-- matrices with conditional formatting, funnels, heatmaps, waterfalls,
-- global filters, per-widget themes and dashboard background images.
--
-- Mechanics mirror the demo-agent seeding: templates live in a hidden
-- table (RLS on, no policies -> service role only), a signup trigger
-- copies them to each new user, and a backfill covers existing users.
-- Widget snapshots were computed from the sample data itself, so the
-- dashboards render instantly and every widget's SQL re-runs cleanly
-- against the local AlaSQL engine on refresh.

CREATE TABLE public.bi_sample_dashboards (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  sort integer NOT NULL,
  name text NOT NULL UNIQUE,
  description text,
  widgets jsonb NOT NULL,
  layout jsonb NOT NULL,
  filters jsonb NOT NULL DEFAULT '[]'::jsonb,
  theme jsonb NOT NULL DEFAULT '{}'::jsonb
);

-- Template store only: RLS with no policies keeps it invisible to clients.
ALTER TABLE public.bi_sample_dashboards ENABLE ROW LEVEL SECURITY;
INSERT INTO public.bi_sample_dashboards (sort, name, description, widgets, layout, filters, theme)
VALUES (1, $sample$Revenue Command Center · Sample$sample$, $sample$Global SaaS revenue FY2022–25 — KPIs, trend & forecast, geography, product mix and profitability. Built on the bundled saas_sales dataset.$sample$, $sample$[{"id":"c9c4cfe3-e915-528f-b0ec-0e5c7ae20175","kind":"text","title":"About this sample","text":"## 🌍 Revenue Command Center\nA **sample project** built on the bundled `saas_sales` dataset (9,994 rows, FY2022–25). Click any bar or slice to **cross-filter** the canvas, use the filter bar to slice by region, segment, industry or date, press ↻ on a widget to re-run its SQL live, or open **Ask AI** and add a visual in plain English. The background is NASA's *Earth at night* — swap it any time via **Theme**."},{"id":"813c2932-e08e-5264-a444-71fe175e0b48","kind":"chart","title":"Total revenue","source":{"kind":"local"},"sql":"SELECT ROUND(SUM(Sales),0) AS [Total Revenue] FROM saas_sales","chart":{"type":"kpi","valueField":"Total Revenue","label":"Total revenue","format":"currency"},"columns":["Total Revenue"],"rows":[{"Total Revenue":2297202}],"refreshed_at":"2026-07-21T12:00:00.000Z","theme":{"card":"glass","accent":"blue"}},{"id":"bd255b89-64b6-59ea-b875-3e2ee021b948","kind":"chart","title":"Total profit","source":{"kind":"local"},"sql":"SELECT ROUND(SUM(Profit),0) AS [Total Profit] FROM saas_sales","chart":{"type":"kpi","valueField":"Total Profit","label":"Total profit","format":"currency"},"columns":["Total Profit"],"rows":[{"Total Profit":286397}],"refreshed_at":"2026-07-21T12:00:00.000Z","theme":{"card":"glass","accent":"emerald"}},{"id":"6abaa6b3-fa3d-5b83-ab04-251c4a0f30af","kind":"chart","title":"Orders","source":{"kind":"local"},"sql":"SELECT COUNT(DISTINCT [Order ID]) AS [Orders] FROM saas_sales","chart":{"type":"kpi","valueField":"Orders","label":"Orders"},"columns":["Orders"],"rows":[{"Orders":5009}],"refreshed_at":"2026-07-21T12:00:00.000Z","theme":{"card":"glass","accent":"violet"}},{"id":"3a0a4d28-0bd9-5112-9c2d-0b848d4b761d","kind":"cha