VALUES (2, $sample$Q3 Budget vs Actual · Sample$sample$, $sample$Finance variance review with a conditionally-formatted matrix, waterfall and utilization gauge. Built on the bundled q3_budget_variance dataset.$sample$, $sample$[{"id":"461e1448-10c5-5899-bebf-980b63a1b375","kind":"text","title":"About this sample","text":"## 💰 Q3 Budget vs Actual\nA **sample project** on the bundled `q3_budget_variance` dataset. The variance matrix uses **conditional-formatting rules** — red where a category ran over budget, green where it came in under. Try the Department filter, click a bar to cross-filter, or ask the AI analyst *“which category drove the overrun?”*"},{"id":"4e943ae8-42e7-5548-ad05-e07efd8f6557","kind":"chart","title":"Q3 budget","source":{"kind":"local"},"sql":"SELECT SUM(Q3_Budget) AS [Total Budget] FROM q3_budget_variance","chart":{"type":"kpi","valueField":"Total Budget","label":"Q3 budget","format":"currency"},"columns":["Total Budget"],"rows":[{"Total Budget":2820000}],"refreshed_at":"2026-07-21T12:00:00.000Z","theme":{"card":"tint","accent":"blue"}},{"id":"4c0e5153-f2f7-5914-b47b-e95cc4514f20","kind":"chart","title":"Q3 actual","source":{"kind":"local"},"sql":"SELECT SUM(Q3_Actual) AS [Total Actual] FROM q3_budget_variance","chart":{"type":"kpi","valueField":"Total Actual","label":"Q3 actual","format":"currency"},"columns":["Total Actual"],"rows":[{"Total Actual":3449500}],"refreshed_at":"2026-07-21T12:00:00.000Z","theme":{"card":"tint","accent":"teal"}},{"id":"b4164461-fbaa-5f9e-a3a0-b494d5748c3d","kind":"chart","title":"Net variance","source":{"kind":"local"},"sql":"SELECT SUM(Variance) AS [Net Variance] FROM q3_budget_variance","chart":{"type":"kpi","valueField":"Net Variance","label":"Net variance (over)","format":"currency"},"columns":["Net Variance"],"rows":[{"Net Variance":629500}],"refreshed_at":"2026-07-21T12:00:00.000Z","theme":{"card":"tint","accent":"rose"}},{"id":"fa38649c-aa0e-5f5b-a408-8c063d0fd51c","kind":"chart","title":"Budget utilization","source":{"kind":"local"},"sql":"SELECT ROUND(SUM(Q3_Actual)*100.0/SUM(Q3_Budget),1) AS [Budget Utilization] FROM q3_budget_variance","chart":{"type":"gauge","valueField":"Budget Utilization","label":"Actual as % of budget","max":150},"columns":["Budget Utilization"],"rows":[{"Budget Utilization":122.3}],"refreshed_at":"2026-07-21T12:00:00.000Z","theme":{"card":"tint","accent":"amber"}},{"id":"4e2edfc8-5df6-5b25-a5ad-e1d6b819814b","kind":"chart","title":"Budget vs actual by department","source":{"kind":"local"},"sql":"SELECT Department, 'Budget' AS [Measure], SUM(Q3_Budget) AS [Amount] FROM q3_budget_variance GROUP BY Department UNION ALL SELECT Department, 'Actual' AS [Measure], SUM(Q3_Actual) AS [Amount] FROM q3_budget_variance GROUP BY Department ORDER BY Department","chart":{"type":"bar","xField":"Department","yField":"Amount","seriesField":"Measure","stacked":false,"format":"currency"},"columns":["Department","Measure","Amount"],"rows":[{"Department":"Engineering","Measure":"Budget","Amount":810000},{"Department":"Engineering","Measure":"Actual","Amount":1115000},{"Department":"HR","Measure":"Budget","Amount":285000},{"Department":"HR","Measure":"Actual","Amount":120000},{"Department":"Legal","Measure":"Budget","Amount":235000},{"Department":"Legal","Measure":"Actual","Amount":466000},{"Department":"Marketing","Measure":"Budget","Amount":635000},{"Department":"Marketing","Measure":"Actual","Amount":776500},{"Department":"Operations","Measure":"Budget","Amount":470000},{"Department":"Operations","Measure":"Actual","Amount":467000},{"Department":"Sales","Measure":"Budget","Amount":385000},{"Department":"Sales","Measure":"Actual","Amount":505000}],"refreshed_at":"2026-07-21T12:00:00.000Z","narrative":"Engineering, Legal, Marketing and Sales all overshot; HR under-spent by $165K."},{"id":"28acc418-6843-599b-86c4-698ac9e9ddf7","kind":"chart","title":"Variance walk by department","source":{"kind":"local"},"sql":"SELECT Department, SUM(Variance) AS [Variance] FROM q3_budget_variance GROUP BY Department ORDER BY [Variance] DESC","chart":{"type":"waterfall","xField":"Department","yField":"Variance","format":"currency"},"columns":["Department","Variance"],"rows":[{"Department":"Engineering","Variance":305000},{"Department":"Legal","Variance":231000},{"Department":"Marketing","Variance":141500},{"Department":"Sales","Variance":120000},{"Department":"Operations","Variance":-3000},{"Department":"HR","Variance":-165000}],"refreshed_at":"2026-07-21T12:00:00.000Z"},{"id":"57d9cc60-823f-5905-8234-4afa84be67b2","kind":"chart","title":"Variance matrix · category × department","source":{"kind":"local"},"sql":"SELECT Category, Department, Variance FROM q3_budget_variance","chart":{"type":"matrix","rowField":"Category","colField":"Department","valueField":"Variance","condFormat":{"mode":"rules","rules":[{"op":"gt","value":0,"color":"rose"},{"op":"lt","value":0,"color":"emerald"},{"op":"eq","value":0,"color":"slate"}]},"format":"currency"},"columns":["Category","Department","Variance"],"rows":[{"Category":"Event Sponsorship","Department":"Marketing","Variance":-105000},{"Category":"Digital Ads","Department":"Marketing","Variance":280000},{"Category":"Software Licenses","Department":"Marketing","Variance":1500},{"Category":"Contractors","Department":"Marketing","Variance":0},{"Category":"Travel & Entertainment","Department":"Marketing","Variance":-35000},{"Category":"Cloud Hosting (AWS)","Department":"Engineering","Variance":215000},{"Category":"Software Licenses","Department":"Engineering","Variance":5000},{"Category":"Hardware/Equipment","Department":"Engineering","Variance":-50000},{"Category":"Contractors","Department":"Engineering","Variance":0},{"Category":"API Usage Fees","Department":"Engineering","Variance":135000},{"Category":"Travel & Entertainment","Department":"Sales","Variance":110000},{"Category":"Client Dinners","Department":"Sales","Variance":35000},{"Category":"Software Licenses","Department":"Sales","Variance":0},{"Category":"Training & Enablement","Department":"Sales","Variance":-25000},{"Category":"Recruiting Fees","Department":"HR","Variance":-90000},{"Category":"Employee Wellbeing","Department":"HR","Variance":5000},{"Category":"Software Licenses","Department":"HR","Variance":0},{"Category":"Offsite Events","Department":"HR","Variance":-80000},{"Category":"Outside Counsel","Department":"Legal","Variance":230000},{"Category":"Software Licenses","Department":"Legal","Variance":1000},{"Category":"Compliance Audits","Department":"Legal","Variance":0},{"Category":"Office Lease","Department":"Operations","Variance":0},{"Category":"Utilities","Department":"Operations","Variance":2000},{"Category":"Shipping & Logistics","Department":"Operations","Variance":-5000}],"refreshed_at":"2026-07-21T12:00:00.000Z"},{"id":"27d64764-f349-5439-9e5b-38fa0dacea0a","kind":"chart","title":"Biggest overruns","source":{"kind":"local"},"sql":"SELECT Category, SUM(Variance) AS [Variance] FROM q3_budget_variance GROUP BY Category HAVING SUM(Variance) > 0 ORDER BY [Variance] DESC","chart":{"type":"hbar","xField":"Category","yField":"Variance","format":"currency"},"columns":["Category","Variance"],"rows":[{"Category":"Digital Ads","Variance":280000},{"Category":"Outside Counsel","Variance":230000},{"Category":"Cloud Hosting (AWS)","Variance":215000},{"Category":"API Usage Fees","Variance":135000},{"Category":"Travel & Entertainment","Variance":75000},{"Category":"Client Dinners","Variance":35000},{"Category":"Software Licenses","Variance":7500},{"Category":"Employee Wellbeing","Variance":5000},{"Category":"Utilities","Variance":2000}],"refreshed_at":"2026-07-21T12:00:00.000Z","theme":{"card":"tint","accent":"rose"}}]$sample$::jsonb, $sample$[{"i":"461e1448-10c5-5899-bebf-980b63a1b375","x":0,"y":0,"w":12,"h":2},{"i":"4e943ae8-42e7-5548-ad05-e07efd8f6557","x":0,"y":2,"w":3,"h":3},{"i":"4c0e5153-f2f7-5914-b47b-e95cc4514f20","x":3,"y":2,"w":3,"h":3},{"i":"b4164461-fbaa-5f9e-a3a0-b494d5748c3d","x":6,"y":2,"w":3,"h":3},