VALUES (3, $sample$Security Operations · Sample$sample$, $sample$SOC overview of SIEM alerts — MITRE ATT&CK techniques, severity mix and the triage pipeline. Built on the bundled siem_alerts dataset.$sample$, $sample$[{"id":"21c9037b-78a1-5398-8a84-f02411f004b2","kind":"text","title":"About this sample","text":"## 🛡️ Security Operations\nA **sample project** on the bundled `siem_alerts` dataset — a SOC-style view of 160 alerts: severity mix, MITRE ATT&CK techniques and the triage pipeline. Use the grain toggle on the area chart to re-bucket by day/week/month, filter by severity or status, and note the **glass** card style over a NASA aurora photo."},{"id":"271cf114-05ee-50ee-84ad-8e08788569b0","kind":"chart","title":"Total alerts","source":{"kind":"local"},"sql":"SELECT COUNT(*) AS [Total Alerts] FROM siem_alerts","chart":{"type":"kpi","valueField":"Total Alerts","label":"Alerts (90 days)"},"columns":["Total Alerts"],"rows":[{"Total Alerts":160}],"refreshed_at":"2026-07-21T12:00:00.000Z","theme":{"card":"glass","accent":"teal"}},{"id":"45486791-5b51-56fe-9769-2d2f524e96cd","kind":"chart","title":"P1 alerts","source":{"kind":"local"},"sql":"SELECT COUNT(*) AS [P1 Alerts] FROM siem_alerts WHERE severity = 'P1'","chart":{"type":"kpi","valueField":"P1 Alerts","label":"P1 · critical severity"},"columns":["P1 Alerts"],"rows":[{"P1 Alerts":33}],"refreshed_at":"2026-07-21T12:00:00.000Z","theme":{"card":"glass","accent":"rose"}},{"id":"b7e38099-2388-5488-bf84-3d6e6534ca58","kind":"chart","title":"Escalated","source":{"kind":"local"},"sql":"SELECT COUNT(*) AS [Escalated] FROM siem_alerts WHERE status = 'ESCALATED'","chart":{"type":"kpi","valueField":"Escalated","label":"Escalated to IR"},"columns":["Escalated"],"rows":[{"Escalated":24}],"refreshed_at":"2026-07-21T12:00:00.000Z","theme":{"card":"glass","accent":"amber"}},{"id":"fc997f0a-4fe9-5cc1-a544-e1130fcd5bb6","kind":"chart","title":"Critical assets","source":{"kind":"local"},"sql":"SELECT COUNT(*) AS [Critical-Asset Aler