-- Copy every sample dashboard to a user (idempotent by name).
CREATE OR REPLACE FUNCTION public.seed_bi_sample_dashboards(_uid uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  INSERT INTO public.bi_dashboards (user_id, name, description, widgets, layout, filters, theme)
  SELECT _uid, s.name, s.description, s.widgets, s.layout, s.filters, s.theme
  FROM public.bi_sample_dashboards s
  WHERE NOT EXISTS (
    SELECT 1 FROM public.bi_dashboards d WHERE d.user_id = _uid AND d.name = s.name
  )
  ORDER BY s.sort;
END;
$$;

-- Additive trigger: runs alongside handle_new_user() on signup.
CREATE OR REPLACE FUNCTION public.handle_new_user_bi_samples()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  PERFORM public.seed_bi_sample_dashboards(NEW.id);
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS on_auth_user_created_bi_samples ON auth.users;
CREATE TRIGGER on_auth_user_created_bi_samples
AFTER INSERT ON auth.users
FOR EACH ROW EXECUTE FUNCTION public.handle_new_user_bi_samples();

-- Backfill: existing accounts get the samples too.
DO $$
DECLARE u record;
BEGIN
  FOR u IN SELECT id FROM auth.users LOOP
    PERFORM public.seed_bi_sample_dashboards(u.id);
  END LOOP;
END;
$$;
